#!/usr/bin/env bash
# SPDX-License-Identifier: MIT
# Atlas KubeKit | By Atlas Richie
# BEGIN ATLAS KUBEKIT VERSION (generated by scripts/update-version.py)
ATLAS_KUBEKIT_VERSION='0.2.0'
if [ "${1:-}" = --version ] || [ "${1:-}" = -V ]; then
  printf 'Atlas KubeKit %s\n' "$ATLAS_KUBEKIT_VERSION"
  exit 0
fi
# END ATLAS KUBEKIT VERSION
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
I18N="$ROOT/scripts/lib/i18n.sh"
[ -r "$I18N" ] || { printf '[ERROR] Missing localization library: %s\n' "$I18N" >&2; exit 1; }
# shellcheck source=scripts/lib/i18n.sh
source "$I18N"

for arg in "$@"; do
  if [ "$arg" = --help ] || [ "$arg" = -h ]; then
    exec python3 "$ROOT/scripts/lb/manager.py" --lang "${ATLAS_LANG:-en}" "$@"
  fi
done
LANG_CODE="${ATLAS_LANG:-}"
if [ -z "$LANG_CODE" ]; then
  atlas_i18n_init en
  atlas_choose_language en || exit 1
  LANG_CODE="$ATLAS_LANG"
else
  atlas_i18n_init "$LANG_CODE"
fi
exec python3 "$ROOT/scripts/lb/manager.py" --lang "$LANG_CODE" "$@"
